import React from 'react';
import { Select, FormItem, FormButtonGroup, Submit } from '@storage-fe/formily-arco';
import { createForm, onFieldReact, FormPathPattern, Field as FieldType } from '@formily/core';
import { FormProvider, Field } from '@formily/react';
import { action } from '@formily/reactive';

const AsyncDataSourceEffect = (
  pattern: FormPathPattern,
  service: (field: FieldType) => Promise<{ label: string; value: any }[]>
) => {
  onFieldReact(pattern, field => {
    const _field = field as FieldType;
    _field.loading = true;
    service(_field).then(
      action.bound?.(data => {
        _field.dataSource = data;
        _field.loading = false;
      })
    );
  });
};

const form = createForm({
  effects: () => {
    AsyncDataSourceEffect('select', async field => {
      const linkage = field.query('linkage').get('value');
      if (!linkage) {
        return [];
      }
      return new Promise(resolve => {
        setTimeout(() => {
          if (linkage === 1) {
            resolve([
              {
                label: 'AAA',
                value: 'aaa',
              },
              {
                label: 'BBB',
                value: 'ccc',
              },
            ]);
          } else if (linkage === 2) {
            resolve([
              {
                label: 'CCC',
                value: 'ccc',
              },
              {
                label: 'DDD',
                value: 'ddd',
              },
            ]);
          }
        }, 1500);
      });
    });
  },
});

export default () => (
  <FormProvider form={form}>
    <Field
      name="linkage"
      title="联动选择框"
      dataSource={[
        { label: '发请求1', value: 1 },
        { label: '发请求2', value: 2 },
      ]}
      decorator={[FormItem]}
      component={[
        Select,
        {
          style: {
            width: 120,
          },
        },
      ]}
    />
    <Field
      name="select"
      title="异步选择框"
      decorator={[FormItem]}
      component={[
        Select,
        {
          style: {
            width: 120,
          },
        },
      ]}
    />
    <FormButtonGroup>
      <Submit onSubmit={console.log}>提交</Submit>
    </FormButtonGroup>
  </FormProvider>
);
